#include "stdlib/blas/ext/base/ndarray/ssome.h"
#include "stdlib/blas/ext/base/ssome.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/blas/base/shared.h"
#include <stdbool.h>
#include <stdint.h>

/**
* Tests whether a one-dimensional single-precision floating-point ndarray contains at least `k` truthy elements.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a zero-dimensional ndarray specifying the minimum number of truthy elements.
*
* @param arrays    list containing ndarrays
* @return          boolean indicating whether the input ndarray contains at least `k` truthy elements
*/
bool stdlib_blas_ext_ssome( const struct ndarray *arrays[] ) {
	const struct ndarray *x = arrays[ 0 ];

	int32_t k;
	stdlib_ndarray_get_int32( arrays[ 1 ], NULL, &k );

	return API_SUFFIX(stdlib_strided_ssome_ndarray)( stdlib_ndarray_dimension( x, 0 ), (CBLAS_INT)k, (const float *)stdlib_ndarray_data( x ), stdlib_ndarray_stride_elements( x, 0 ), stdlib_ndarray_offset_elements( x ) );
}
